css:
.d-hr{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;width:100%;max-width:340px;height:180px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden;touch-action:none}
.d-hr-btn{position:relative;display:inline-flex;align-items:center;gap:8px;padding:12px 22px;border:1px solid var(--ink);border-radius:999px;background:var(--paper);color:var(--ink);font:inherit;font-size:13px;cursor:pointer;transition:transform 160ms var(--ease-physical),background-color 160ms var(--ease)}
.d-hr-btn span{display:block;width:8px;height:8px;border-radius:50%;background:var(--ink-vermilion);opacity:0;transition:opacity 120ms var(--ease)}
.d-hr-btn.on{transform:scale(1.04);background:var(--ink);color:var(--paper)}
.d-hr-btn.on span{opacity:1;animation:d-hold-to-record-blink 1s steps(2) infinite}
.d-hr-btn.cancel{background:var(--ink-vermilion);border-color:var(--ink-vermilion);color:var(--paper)}
.d-hr-note{position:absolute;bottom:10px;margin:0;font-family:var(--font-mono);font-size:9px;letter-spacing:.06em;color:var(--faint)}
@keyframes d-hold-to-record-blink{50%{opacity:.25}}

init:
root => {
  var btn = root.querySelector('[data-rec]');
  var note = root.querySelector('[data-note]');
  if (!btn) return;
  var t0 = 0, startY = 0, timer = 0, on = false, cancelled = false;
  var fmt = function (ms) { var s = ms / 1000; return s.toFixed(1) + 's'; };
  var stop = function () {
    if (!on) return;
    on = false;
    clearInterval(timer);
    btn.classList.remove('on', 'cancel');
    btn.lastChild.textContent = '按住说话';
    var ms = performance.now() - t0;
    if (note) note.textContent = cancelled ? '已取消' : '录了 ' + fmt(ms);
  };
  btn.addEventListener('pointerdown', function (e) {
    e.preventDefault();
    on = true; cancelled = false; t0 = performance.now(); startY = e.clientY;
    btn.classList.add('on');
    btn.lastChild.textContent = '松手结束';
    btn.setPointerCapture(e.pointerId);
    timer = setInterval(function () { if (note) note.textContent = fmt(performance.now() - t0) + ' · 上滑取消'; }, 100);
  });
  btn.addEventListener('pointermove', function (e) {
    if (!on) return;
    var up = startY - e.clientY;
    cancelled = up > 60;
    btn.classList.toggle('cancel', cancelled);
    if (note) note.textContent = cancelled ? '松手取消' : fmt(performance.now() - t0) + ' · 上滑取消';
  });
  btn.addEventListener('pointerup', stop);
  btn.addEventListener('pointercancel', stop);
}
